if (collides(state.ball, brick)) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Calculate collision normal to determine bounce direction
  const ballLeft = state.ball.x - state.ball.r;
  const ballRight = state.ball.x + state.ball.r;
  const ballTop = state.ball.y - state.ball.r;
  const ballBottom = state.ball.y + state.ball.r;

  const brickLeft = brick.x;
  const brickRight = brick.x + brick.w;
  const brickTop = brick.y;
  const brickBottom = brick.y + brick.h;

  // Find the overlap on each axis
  const overlapX = Math.min(ballRight - brickLeft, brickRight - ballLeft);
  const overlapY = Math.min(ballBottom - brickTop, brickBottom - ballTop);

  if (overlapX < overlapY) {
    // Collision on the sides
    state.ball.vx = -state.ball.vx;
    if (state.ball.vx > 0) {
      state.ball.x = brickRight + state.ball.r;
    } else {
      state.ball.x = brickLeft - state.ball.r;
    }
  } else {
    // Collision on top or bottom
    state.ball.vy = -state.ball.vy;
    if (state.ball.vy > 0) {
      state.ball.y = brickBottom + state.ball.r;
    } else {
      state.ball.y = brickTop - state.ball.r;
    }
  }
}

